&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;About Ogilvy: &lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;eop&quot;&gt; &lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;Ogilvy UK has been creating iconic ideas that deliver impact at scale for clients ever since David Ogilvy founded the company in 1948. Ogilvy UK specialises in bringing together brand advertising, customer experience marketing, PR, &lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;influence&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt; and consulting, all fuelled by Behavioural Science. Our world-class award-winning creative campaigns deliver solutions for clients including Sainsbury’s, Argos&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;, ,&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt; Mondelēz International, Unilever, TK &lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;Maxx&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt; and Pernod Ricard.  &lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;scxw40112971&quot; data-ccp-charstyle-defn=&quot;{&amp;quot;ObjectId&amp;quot;:&amp;quot;c8606303-8a6a-57a4-9e75-879ecb129bcc|1&amp;quot;,&amp;quot;ClassId&amp;quot;:1073872969,&amp;quot;Properties&amp;quot;:[201342446,&amp;quot;1&amp;quot;,201342447,&amp;quot;5&amp;quot;,201342448,&amp;quot;1&amp;quot;,201342449,&amp;quot;1&amp;quot;,469777841,&amp;quot;Aptos&amp;quot;,469777842,&amp;quot;&amp;quot;,469777843,&amp;quot;Aptos&amp;quot;,469777844,&amp;quot;Aptos&amp;quot;,201341986,&amp;quot;1&amp;quot;,469769226,&amp;quot;Aptos&amp;quot;,268442635,&amp;quot;24&amp;quot;,469775450,&amp;quot;scxw40112971&amp;quot;,201340122,&amp;quot;1&amp;quot;,134233614,&amp;quot;true&amp;quot;,469778129,&amp;quot;scxw40112971&amp;quot;,335572020,&amp;quot;1&amp;quot;,469778324,&amp;quot;Default Paragraph Font&amp;quot;]}&quot;&gt; &lt;/span&gt;&lt;/span&gt;&amp;nbsp;&lt;br&gt;&lt;span data-contrast=&quot